#!/usr/bin/env python3
"""Generate Go concept artifacts from the canonical Python domain table."""

from __future__ import annotations

import argparse
import json
import sys
from dataclasses import asdict
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from backend.app.domain.project_search_concepts import PROJECT_CONCEPT_LEXICON


def generated_files() -> dict[Path, str]:
    def quote(value: str) -> str:
        return json.dumps(value, ensure_ascii=False)
    lines = [
        "// Code generated by scripts/sync_project_search_concepts.py; DO NOT EDIT.",
        "// Source: backend/app/domain/project_search_concepts.py",
        "package projectsem", "", "type conceptSpec struct {",
        "\tconceptID string", "\tphrases   []string", "\taliases   []string", "}", "",
        "var projectConceptLexicon = []conceptSpec{",
    ]
    for spec in PROJECT_CONCEPT_LEXICON:
        lines.extend([
            "\t{", f"\t\tconceptID: {quote(spec.concept_id)},",
            "\t\tphrases:   []string{" + ", ".join(map(quote, spec.phrases)) + "},",
            "\t\taliases:   []string{" + ", ".join(map(quote, spec.aliases)) + "},", "\t},",
        ])
    lines.append("}")
    return {
        Path("mcp-go/internal/projectsem/lexicon.go"): "\n".join(lines) + "\n",
        Path("mcp-go/internal/projectsem/testdata/lexicon.json"): json.dumps(
            [asdict(spec) for spec in PROJECT_CONCEPT_LEXICON], ensure_ascii=False, indent=1,
        ) + "\n",
    }


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Fail if generated artifacts drift.")
    args = parser.parse_args()
    stale = []
    for relative, expected in generated_files().items():
        path = ROOT / relative
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != expected:
                stale.append(str(relative))
        else:
            path.write_text(expected, encoding="utf-8")
    if stale:
        print("Run python scripts/sync_project_search_concepts.py: " + ", ".join(stale), file=sys.stderr)
    return int(bool(stale))


if __name__ == "__main__":
    raise SystemExit(main())
